import heapq
class Solution:
    def minimumCost(self, start: List[int], target: List[int], specialRoads: List[List[int]]) -> int:
        pts = [(start[0], start[1]), (target[0], target[1])]
        for x1, y1, x2, y2, c in specialRoads:
            pts.append((x1, y1)); pts.append((x2, y2))
        idx = {p: i for i, p in enumerate(pts)}
        n = len(pts)
        man = lambda a, b: abs(a[0]-b[0]) + abs(a[1]-b[1])
        adj = [[man(pts[i], pts[j]) for j in range(n)] for i in range(n)]
        for x1, y1, x2, y2, c in specialRoads:
            a, b = idx[(x1, y1)], idx[(x2, y2)]
            adj[a][b] = min(adj[a][b], c)
        dist = [float('inf')] * n
        dist[0] = 0
        pq = [(0, 0)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]: continue
            for v in range(n):
                nd = d + adj[u][v]
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        return dist[1]

