        vector<array<int,2>> pts = {{start[0],start[1]},{target[0],target[1]}};
        for (auto& r : sp) { pts.push_back({r[0],r[1]}); pts.push_back({r[2],r[3]}); }
        int n = pts.size();
        auto man = [&](int i, int j){ return abs(pts[i][0]-pts[j][0]) + abs(pts[i][1]-pts[j][1]); };
        vector<vector<int>> adj(n, vector<int>(n));
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) adj[i][j] = man(i, j);
        for (auto& r : sp) {
            int a = -1, b = -1;
            for (int i = 0; i < n; i++) {
                if (pts[i][0] == r[0] && pts[i][1] == r[1]) a = i;
                if (pts[i][0] == r[2] && pts[i][1] == r[3]) b = i;
            }
            adj[a][b] = min(adj[a][b], r[4]);
        }
        vector<long long> dist(n, LLONG_MAX); dist[0] = 0;
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        pq.push({0, 0});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            for (int v = 0; v < n; v++)
                if (d + adj[u][v] < dist[v]) { dist[v] = d + adj[u][v]; pq.push({dist[v], v}); }
        }
        return (int)dist[1];
    }
};

