        int n = pts.size();
        int[][] adj = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                adj[i][j] = Math.abs(pts.get(i)[0]-pts.get(j)[0]) + Math.abs(pts.get(i)[1]-pts.get(j)[1]);
        for (int[] r : sp) {
            int a = 0, b = 0;
            for (int i = 0; i < n; i++) {
                if (pts.get(i)[0] == r[0] && pts.get(i)[1] == r[1]) a = i;
                if (pts.get(i)[0] == r[2] && pts.get(i)[1] == r[3]) b = i;
            }
            adj[a][b] = Math.min(adj[a][b], r[4]);
        }
        long[] dist = new long[n]; Arrays.fill(dist, Long.MAX_VALUE); dist[0] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
        pq.add(new long[]{0, 0});
        while (!pq.isEmpty()) {
            long[] top = pq.poll(); long d = top[0]; int u = (int) top[1];
            if (d > dist[u]) continue;
