var minimumCost = function(start, target, specialRoads) {
    const pts = [[start[0], start[1]], [target[0], target[1]]];
    for (const [x1, y1, x2, y2] of specialRoads) { pts.push([x1, y1]); pts.push([x2, y2]); }
    const idx = new Map(pts.map((p, i) => [p.join(','), i]));
    const n = pts.length;
    const man = (i, j) => Math.abs(pts[i][0]-pts[j][0]) + Math.abs(pts[i][1]-pts[j][1]);
    const adj = Array.from({length: n}, (_, i) => Array.from({length: n}, (_, j) => man(i, j)));
    for (const [x1, y1, x2, y2, c] of specialRoads) {
        const a = idx.get([x1, y1].join(',')), b = idx.get([x2, y2].join(','));
        adj[a][b] = Math.min(adj[a][b], c);
    }
    const dist = new Array(n).fill(Infinity); dist[0] = 0;
    const pq = [[0, 0]];
    while (pq.length) {
        const [d, u] = pq.shift();
        if (d > dist[u]) continue;
        for (let v = 0; v < n; v++)
            if (d + adj[u][v] < dist[v]) { dist[v] = d + adj[u][v]; pq.push([dist[v], v]); pq.sort((a, b) => a[0] - b[0]); }
    }
    return dist[1];
};

